import sys

def main():
    data = sys.stdin.read().split()
    if len(data) < 2:
        return

    a, b = data[0], data[1]

    direcoes = {
        "norte": 0,
        "leste": 90,
        "sul": 180,
        "oeste": 270
    }

    diff = abs(direcoes[a] - direcoes[b])
    print(min(diff, 360 - diff))

if __name__ == "__main__":
    main()
